	@Test
	void queryReadyShardIsCompressedLazyAndChecksummed(@TempDir Path directory) throws Exception {
		Path path = directory.resolve("statistics-7-3.fs2");
		long[] terms = { 0L, 1L, 17L, (1L << 34) + 3L, 19_999_999_999L, 20_000_000_000L };
		long[] postings = { 100L, 100L, 101L, 1_000L, 1_000_000L, 9_000_000_000L };
		writeShard(path, terms, postings);

		try (FrontierStatisticsShard shard = FrontierStatisticsShard.open(path)) {
			assertEquals(7L, shard.generationId());
			assertEquals(3, shard.shardId());
			assertEquals(11L, shard.snapshotEpoch());
			assertEquals(20_000_000_000L, shard.maximumTermId());
			assertEquals(terms.length, shard.rowCount());
			assertEquals(2, shard.columnCount());
			assertEquals(0, shard.mappedDataBlockCount(),
					"opening a shard must map only its header and directory");

			FrontierStatisticsShard.ColumnReader termColumn = shard.column(10);
			assertEquals(35, termColumn.bitWidth());
			assertEquals(0, shard.mappedDataBlockCount());
			for (int row = 0; row < terms.length; row++) {
				assertEquals(terms[row], termColumn.value(row));
			}
			assertEquals(1, shard.mappedDataBlockCount());

			FrontierStatisticsShard.ColumnReader postingColumn = shard.column(20);
			for (int row = 0; row < postings.length; row++) {
				assertEquals(postings[row], postingColumn.value(row));
			}
			assertEquals(2, shard.mappedDataBlockCount());
			assertEquals(Files.size(path), shard.fileLength());
			assertTrue(shard.fileLength() < FrontierStatisticsShard.MAXIMUM_SHARD_BYTES);
		}
	}

	@Test
	void dataChecksumIsLazyWhileTruncationFailsAtOpen(@TempDir Path directory) throws Exception {
		long[] terms = { 11L, 12L, 13L };
		long[] postings = { 100L, 200L, 300L };
		Path corrupt = directory.resolve("corrupt.fs2");
		writeShard(corrupt, terms, postings);
		long dataOffset;
		try (FrontierStatisticsShard shard = FrontierStatisticsShard.open(corrupt)) {
			dataOffset = shard.column(10).dataOffset();
			assertEquals(0, shard.mappedDataBlockCount());
		}
		try (FileChannel channel = FileChannel.open(corrupt, StandardOpenOption.READ, StandardOpenOption.WRITE)) {
			ByteBuffer oneByte = ByteBuffer.allocate(1);
			assertEquals(1, channel.read(oneByte, dataOffset));
			oneByte.flip();
			byte changed = (byte) (oneByte.get() ^ 0x01);
			oneByte.clear();
			oneByte.put(changed).flip();
			assertEquals(1, channel.write(oneByte, dataOffset));
			channel.force(true);
		}
		try (FrontierStatisticsShard shard = FrontierStatisticsShard.open(corrupt)) {
			assertEquals(0, shard.mappedDataBlockCount(),
					"data corruption must remain lazy until the block is first used");
			IOException failure = assertThrows(IOException.class, () -> shard.column(10).value(0));
			assertNotNull(failure.getMessage());
		}

		Path truncated = directory.resolve("truncated.fs2");
		writeShard(truncated, terms, postings);
		try (FileChannel channel = FileChannel.open(truncated, StandardOpenOption.WRITE)) {
			channel.truncate(channel.size() - 1L);
		}
		assertThrows(IOException.class, () -> FrontierStatisticsShard.open(truncated));
	}

