	@Test
	void packedColumnsMapAndValidateOnlyTheAddressedOneMiBBlock(@TempDir Path directory) throws Exception {
		int bitWidth = 35;
		int targetBlockBytes = 1 << 20;
		int rowsPerBlock = Math.toIntExact((long) targetBlockBytes * Byte.SIZE / bitWidth);
		int rows = rowsPerBlock * 2 + 17;
		long[] terms = new long[rows];
		for (int row = 0; row < rows; row++) {
			terms[row] = 17_000_000_000L + row;
		}
		Path path = directory.resolve("block-local.fs2");
		try (FrontierStatisticsShardWriter writer = new FrontierStatisticsShardWriter(
				path, 12L, 8, 19L, 20_000_000_000L, rows)) {
			writer.addTermColumn(10, terms);
			writer.finish();
		}

		long dataOffset;
		try (FrontierStatisticsShard shard = FrontierStatisticsShard.open(path)) {
			FrontierStatisticsShard.ColumnReader column = shard.column(10);
			dataOffset = column.dataOffset();
			assertEquals(terms[0], column.value(0));
			assertEquals(1, shard.mappedDataBlockCount());
			assertEquals(terms[rows - 1], column.value(rows - 1));
			assertEquals(2, shard.mappedDataBlockCount(),
					"reading a distant row must map a second bounded data block, not one whole column");
		}

		long firstBlockBytes = ((long) rowsPerBlock * bitWidth + Byte.SIZE - 1L) / Byte.SIZE;
		long corruptOffset = dataOffset + firstBlockBytes + 7L;
		try (FileChannel channel = FileChannel.open(path, StandardOpenOption.READ, StandardOpenOption.WRITE)) {
			ByteBuffer byteBuffer = ByteBuffer.allocate(1);
			assertEquals(1, channel.read(byteBuffer, corruptOffset));
			byteBuffer.flip();
			byte changed = (byte) (byteBuffer.get() ^ 0x40);
			byteBuffer.clear();
			byteBuffer.put(changed).flip();
			assertEquals(1, channel.write(byteBuffer, corruptOffset));
			channel.force(true);
		}
		try (FrontierStatisticsShard shard = FrontierStatisticsShard.open(path)) {
			FrontierStatisticsShard.ColumnReader column = shard.column(10);
			assertEquals(terms[0], column.value(0),
					"corruption in an untouched block must not invalidate the first block");
			assertThrows(IOException.class, () -> column.value(rowsPerBlock));
		}
	}

